/**
 * __NAME__ — generated by `uniplug init`.
 *
 * The whole plugin API is on `api`; nothing else needs importing.
 * Full reference: ../docs/API.md
 */

import { definePlugin } from '__IMPORT__';

export default definePlugin({
  setup(api) {
    api.log.info('setup');

    // Commands: `uniplug run __ID__:hello`
    api.command(
      '__ID__:hello',
      (name = 'world') => `hello ${name}`,
      'Say hello',
    );

    // Events: anything can emit `__ID__:ping`.
    api.on('__ID__:ping', (payload) => {
      api.log.info('received ping', payload);
      return { ok: true };
    });

    // Config values come from plugin.json `config` + config/__ID__.json.
    api.log.debug('enabledMessage =', api.config.get('enabledMessage'));
  },

  async onEnable(api) {
    api.log.info('enabled');
  },

  async onDisable(api) {
    api.log.info('disabled');
  },
});
